"""
views/vm_detail_view.py — detail pane for a selected VM.

Duplication fix: identity rows are tracked in self._identity_rows and
removed by direct reference — never by walking PreferencesGroup internals.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, GLib, Gdk
import libvirt

from ..backend.libvirt_manager import (
    LibvirtManager, DomainInfo, TRUST_LABELS, TRUST_LEVELS, DEFAULT_TRUST_LEVELS
)
from .trust_editor_dialog import TrustEditorDialog

# Trust levels available to assign to non-system VMs
_ASSIGNABLE_TRUST = [k for k in DEFAULT_TRUST_LEVELS if k != "system" and k != "unknown"]


class VMDetailView(Gtk.Box):
    def __init__(self, manager: LibvirtManager):
        super().__init__(orientation=Gtk.Orientation.VERTICAL)
        self._mgr  = manager
        self._info: DomainInfo | None = None
        self._poll_source: int | None = None

        # Track rows so we can remove them by reference (fixes duplication bug)
        self._identity_rows: list[Adw.ActionRow] = []
        self._trust_row_idx: int = 0   # index into _ASSIGNABLE_TRUST

        # ── Header bar ────────────────────────────────────────────────────
        self._header = Adw.HeaderBar()

        # Trust editor button
        btn_trust_mgr = Gtk.Button()
        btn_trust_mgr.set_icon_name("preferences-other-symbolic")
        btn_trust_mgr.set_tooltip_text("Manage trust levels")
        btn_trust_mgr.connect("clicked", self._on_open_trust_editor)
        self._header.pack_end(btn_trust_mgr)

        self.append(self._header)

        # ── Scrollable body ───────────────────────────────────────────────
        clamp = Adw.Clamp()
        clamp.set_maximum_size(680)
        clamp.set_margin_top(16)
        clamp.set_margin_bottom(16)
        clamp.set_margin_start(16)
        clamp.set_margin_end(16)

        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
        scroll.set_vexpand(True)
        scroll.set_child(clamp)

        body = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=16)
        clamp.set_child(body)

        # ── Error banner ──────────────────────────────────────────────────
        self._error_banner = Adw.Banner()
        self._error_banner.set_revealed(False)
        body.append(self._error_banner)

        # ── Power button toolbar ──────────────────────────────────────────
        btn_box = Gtk.Box(
            orientation=Gtk.Orientation.HORIZONTAL,
            spacing=8,
            homogeneous=True,
        )
        btn_box.add_css_class("linked")

        def _tb(icon, tooltip, style, cb):
            b = Gtk.Button()
            b.set_icon_name(icon)
            b.set_tooltip_text(tooltip)
            b.set_hexpand(True)
            if style:
                b.add_css_class(style)
            b.connect("clicked", cb)
            btn_box.append(b)
            return b

        self._btn_start    = _tb("media-playback-start-symbolic",  "Start",       "suggested-action",   self._on_start)
        self._btn_shutdown = _tb("system-shutdown-symbolic",        "Shutdown",    "",                   self._on_shutdown)
        self._btn_restart  = _tb("system-reboot-symbolic",          "Restart",     "",                   self._on_restart)
        self._btn_reset    = _tb("view-refresh-symbolic",           "Hard reset",  "",                   self._on_reset)
        self._btn_force    = _tb("process-stop-symbolic",           "Force stop",  "destructive-action", self._on_force_stop)
        self._btn_pause    = _tb("media-playback-pause-symbolic",   "Pause",       "",                   self._on_pause)
        self._btn_resume   = _tb("media-playback-start-symbolic",   "Resume",      "",                   self._on_resume)

        body.append(btn_box)

        # Console button — full width below the toolbar
        self._btn_console = Gtk.Button(label="Open Console")
        self._btn_console.set_icon_name("utilities-terminal-symbolic")
        self._btn_console.add_css_class("suggested-action")
        self._btn_console.connect("clicked", self._on_console)
        body.append(self._btn_console)

        # ── Identity group ────────────────────────────────────────────────
        self._identity_group = Adw.PreferencesGroup()
        self._identity_group.set_title("Identity")
        body.append(self._identity_group)

        # ── Trust & display group (hidden for system VMs) ─────────────────
        self._trust_group = Adw.PreferencesGroup()
        self._trust_group.set_title("Trust & display")
        body.append(self._trust_group)

        # Display label
        self._label_row = Adw.EntryRow()
        self._label_row.set_title("Display label")
        self._label_row.connect("apply", self._on_label_apply)
        self._trust_group.add(self._label_row)

        # Trust level combo — populated dynamically from manager defs
        self._trust_combo = Adw.ComboRow()
        self._trust_combo.set_title("Trust level")
        self._trust_combo_keys: list[str] = []   # initialised here, rebuilt in _render_trust_editor
        self._trust_combo.connect("notify::selected", self._on_trust_changed)
        self._trust_group.add(self._trust_combo)

        # ── Stats group ───────────────────────────────────────────────────
        self._stats_group = Adw.PreferencesGroup()
        self._stats_group.set_title("Resource usage")
        body.append(self._stats_group)

        self._stat_cpu  = self._make_stat_row("CPU time")
        self._stat_mem  = self._make_stat_row("Memory")
        self._stat_vcpu = self._make_stat_row("vCPUs")
        for r in (self._stat_cpu, self._stat_mem, self._stat_vcpu):
            self._stats_group.add(r)

        # ── Settings group ────────────────────────────────────────────────
        settings_group = Adw.PreferencesGroup()
        settings_group.set_title("Settings")
        body.append(settings_group)

        self._autostart_row = Adw.SwitchRow()
        self._autostart_row.set_title("Autostart")
        self._autostart_row.set_subtitle("Start this VM automatically when the host boots")
        self._autostart_row.connect("notify::active", self._on_autostart_toggled)
        settings_group.add(self._autostart_row)

        delete_row = Adw.ActionRow()
        delete_row.set_title("Delete VM")
        delete_row.set_subtitle("Permanently remove this virtual machine")
        delete_btn = Gtk.Button(label="Delete…")
        delete_btn.add_css_class("destructive-action")
        delete_btn.set_valign(Gtk.Align.CENTER)
        delete_btn.connect("clicked", self._on_delete)
        delete_row.add_suffix(delete_btn)
        settings_group.add(delete_row)

        # ── Toast overlay ─────────────────────────────────────────────────
        self._toast_overlay = Adw.ToastOverlay()
        self._toast_overlay.set_child(scroll)
        self.append(self._toast_overlay)

    # ------------------------------------------------------------------ #
    # Public API                                                           #
    # ------------------------------------------------------------------ #

    def load(self, info: DomainInfo):
        """Full refresh — called when user selects a VM."""
        self._stop_polling()
        self._info = info
        self._render_identity(info)       # clears old rows before adding new ones
        self._render_controls(info)
        self._render_trust_editor(info)
        self._render_autostart(info)
        self._render_stats({})
        if info.is_running:
            self._start_polling()

    def refresh(self, info: DomainInfo):
        """Lightweight state-change update."""
        self._info = info
        self._render_controls(info)
        if info.is_running:
            self._start_polling()
        else:
            self._stop_polling()
            self._render_stats({})

    # ------------------------------------------------------------------ #
    # Identity — duplication fix                                           #
    # ------------------------------------------------------------------ #

    def _render_identity(self, info: DomainInfo):
        # Remove previously added rows by direct reference.
        # Do NOT iterate get_first_child() — PreferencesGroup wraps rows
        # in internal widgets and that approach removes the wrong nodes.
        for row in self._identity_rows:
            self._identity_group.remove(row)
        self._identity_rows.clear()

        trust_id    = info.meta.get("trust", "unknown")
        defs        = self._mgr.get_trust_defs()
        trust_defn  = defs.get(trust_id, defs.get("unknown", {}))
        trust_label = trust_defn.get("label", trust_id.capitalize())
        trust_color = trust_defn.get("color", "#888888")

        rows_data = [
            ("VM name",     info.name),
            ("Trust level", trust_label),
            ("UUID",        info.uuid),
            ("vCPUs",       str(info.vcpus)),
            ("Max memory",  f"{info.max_memory_kb // 1024} MB"),
        ]

        for title, value in rows_data:
            row = Adw.ActionRow()
            row.set_title(title)

            if title == "Trust level":
                # Colour dot before the value
                dot = Gtk.DrawingArea()
                dot.set_size_request(12, 12)
                dot.set_valign(Gtk.Align.CENTER)

                def draw_dot(da, cr, w, h, hex_=trust_color):
                    rgba = Gdk.RGBA()
                    rgba.parse(hex_)
                    cr.set_source_rgba(rgba.red, rgba.green, rgba.blue, 1.0)
                    cr.arc(w / 2, h / 2, w / 2, 0, 2 * 3.14159)
                    cr.fill()

                dot.set_draw_func(draw_dot)

                lbl = Gtk.Label(label=value)
                lbl.add_css_class("dim-label")

                suffix_box = Gtk.Box(spacing=6)
                suffix_box.set_valign(Gtk.Align.CENTER)
                suffix_box.append(dot)
                suffix_box.append(lbl)
                row.add_suffix(suffix_box)
            else:
                val = Gtk.Label(label=value)
                val.add_css_class("monospace")
                val.add_css_class("dim-label")
                val.set_selectable(True)
                row.add_suffix(val)

            self._identity_group.add(row)
            self._identity_rows.append(row)   # track for clean removal next time

    # ------------------------------------------------------------------ #
    # Trust editor                                                         #
    # ------------------------------------------------------------------ #

    def _render_trust_editor(self, info: DomainInfo):
        locked = info.is_system_locked
        self._trust_group.set_visible(not locked)
        if locked:
            return

        # Rebuild trust combo from live defs (user may have added custom levels)
        defs = self._mgr.get_trust_defs()
        assignable = [(k, v) for k, v in sorted(defs.items(), key=lambda x: x[1].get("sort", 99))
                      if k not in ("system", "unknown")]
        self._trust_combo_keys = [k for k, _ in assignable]

        self._trust_combo.disconnect_by_func(self._on_trust_changed)
        model = Gtk.StringList()
        for _, defn in assignable:
            model.append(defn.get("label", "?"))
        self._trust_combo.set_model(model)

        current = info.meta.get("trust", "unknown")
        idx = self._trust_combo_keys.index(current) if current in self._trust_combo_keys else 0
        self._trust_combo.set_selected(idx)
        self._trust_combo.connect("notify::selected", self._on_trust_changed)

        # Label entry
        self._label_row.set_text(info.meta.get("label", info.name))

    def _on_label_apply(self, row):
        if not self._info or self._info.is_system_locked:
            return
        ok, msg = self._mgr.set_label(self._info.name, row.get_text().strip())
        self._toast(msg, error=not ok)

    def _on_trust_changed(self, combo, _param):
        if not self._info or self._info.is_system_locked:
            return
        keys = self._trust_combo_keys
        idx  = combo.get_selected()
        # GTK_INVALID_LIST_POSITION is 0xffffffff — guard against it
        if not keys or idx == 0xffffffff or idx >= len(keys):
            return
        trust   = keys[idx]
        ok, msg = self._mgr.set_trust(self._info.name, trust)
        self._toast(msg, error=not ok)
        # Refresh identity to update trust colour dot
        self._render_identity(self._info)

    def _on_open_trust_editor(self, _btn):
        dialog = TrustEditorDialog(manager=self._mgr, parent=self)
        dialog.present(self)
        # After dialog closes the manager will _notify() which triggers a refresh

    # ------------------------------------------------------------------ #
    # Controls                                                             #
    # ------------------------------------------------------------------ #

    def _render_controls(self, info: DomainInfo):
        running = info.is_running
        stopped = info.is_stopped
        paused  = info.is_paused

        self._btn_start.set_sensitive(stopped)
        self._btn_shutdown.set_sensitive(running)
        self._btn_restart.set_sensitive(running)
        self._btn_reset.set_sensitive(running)
        self._btn_force.set_sensitive(running or paused)
        self._btn_pause.set_sensitive(running)
        self._btn_resume.set_sensitive(paused)
        self._btn_console.set_sensitive(running)

    # ------------------------------------------------------------------ #
    # Stats                                                                #
    # ------------------------------------------------------------------ #

    def _make_stat_row(self, label: str) -> Adw.ActionRow:
        row = Adw.ActionRow()
        row.set_title(label)
        lbl = Gtk.Label(label="—")
        lbl.add_css_class("monospace")
        lbl.add_css_class("dim-label")
        row.add_suffix(lbl)
        row._value_label = lbl  # type: ignore[attr-defined]
        return row

    def _render_stats(self, stats: dict):
        if not stats:
            for r in (self._stat_cpu, self._stat_mem, self._stat_vcpu):
                r._value_label.set_label("—")  # type: ignore
            return
        cpu_sec = stats.get("cpu_time_ns", 0) / 1_000_000_000
        mem_mb  = stats.get("memory_kb", 0) // 1024
        max_mb  = stats.get("max_mem_kb", 0) // 1024
        self._stat_cpu._value_label.set_label(f"{cpu_sec:.1f}s total")   # type: ignore
        self._stat_mem._value_label.set_label(f"{mem_mb} / {max_mb} MB") # type: ignore
        self._stat_vcpu._value_label.set_label(str(stats.get("vcpus", 0))) # type: ignore

    def _start_polling(self):
        if self._poll_source is not None:
            return
        self._poll_source = GLib.timeout_add_seconds(2, self._poll_stats)

    def _stop_polling(self):
        if self._poll_source is not None:
            GLib.source_remove(self._poll_source)
            self._poll_source = None

    def _poll_stats(self) -> bool:
        if not self._info or not self._info.is_running:
            self._poll_source = None
            return GLib.SOURCE_REMOVE
        self._render_stats(self._mgr.get_stats(self._info.name))
        return GLib.SOURCE_CONTINUE

    # ------------------------------------------------------------------ #
    # Autostart                                                            #
    # ------------------------------------------------------------------ #

    def _render_autostart(self, info: DomainInfo):
        domain  = self._mgr.get_domain(info.name)
        enabled = False
        if domain:
            try:
                enabled = bool(domain.autostart())
            except libvirt.libvirtError:
                pass
        self._autostart_row.handler_block_by_func(self._on_autostart_toggled)
        self._autostart_row.set_active(enabled)
        self._autostart_row.handler_unblock_by_func(self._on_autostart_toggled)

    def _on_autostart_toggled(self, row, _param):
        if not self._info:
            return
        domain = self._mgr.get_domain(self._info.name)
        if not domain:
            return
        try:
            domain.setAutostart(1 if row.get_active() else 0)
            state = "enabled" if row.get_active() else "disabled"
            self._toast(f"Autostart {state}.")
        except libvirt.libvirtError as e:
            self._toast(f"Failed to set autostart: {e}", error=True)

    # ------------------------------------------------------------------ #
    # Power handlers                                                       #
    # ------------------------------------------------------------------ #

    def _act(self, fn, *args):
        ok, msg = fn(*args)
        self._toast(msg, error=not ok)

    def _on_start(self, _):
        if self._info:
            self._act(self._mgr.start_domain, self._info.name)

    def _on_shutdown(self, _):
        if not self._info:
            return
        self._confirm(
            heading=f"Shut down {self._info.meta.get('label', self._info.name)}?",
            body="The VM will receive an ACPI shutdown signal. Unsaved work may be lost.",
            action_label="Shut Down", action_id="shutdown",
            on_confirm=lambda: self._act(self._mgr.shutdown_domain, self._info.name),
            destructive=True,
        )

    def _on_restart(self, _):
        if self._info:
            self._act(self._mgr.restart_domain, self._info.name)

    def _on_reset(self, _):
        if not self._info:
            return
        self._confirm(
            heading=f"Hard reset {self._info.meta.get('label', self._info.name)}?",
            body="Equivalent to pressing the physical reset button. Unsaved work may be lost.",
            action_label="Reset", action_id="reset",
            on_confirm=lambda: self._act(self._mgr.reset_domain, self._info.name),
            destructive=True,
        )

    def _on_force_stop(self, _):
        if not self._info:
            return
        self._confirm(
            heading=f"Force stop {self._info.meta.get('label', self._info.name)}?",
            body="Equivalent to cutting power. Data loss may occur.",
            action_label="Force Stop", action_id="stop",
            on_confirm=lambda: self._act(self._mgr.force_stop_domain, self._info.name),
            destructive=True,
        )

    def _on_pause(self, _):
        if self._info:
            self._act(self._mgr.pause_domain, self._info.name)

    def _on_resume(self, _):
        if self._info:
            self._act(self._mgr.resume_domain, self._info.name)

    def _on_console(self, _):
        if self._info:
            self._act(self._mgr.open_console, self._info.name)

    # ------------------------------------------------------------------ #
    # Delete                                                               #
    # ------------------------------------------------------------------ #

    def _on_delete(self, _):
        if not self._info:
            return
        self._confirm(
            heading=f"Delete {self._info.meta.get('label', self._info.name)}?",
            body="This will undefine the VM. The disk image will not be deleted.",
            action_label="Delete VM", action_id="delete",
            on_confirm=lambda: self._act(self._mgr.delete_domain, self._info.name, False),
            destructive=True,
        )

    # ------------------------------------------------------------------ #
    # Helpers                                                              #
    # ------------------------------------------------------------------ #

    def _confirm(self, heading, body, action_label, action_id, on_confirm, destructive=False):
        dialog = Adw.MessageDialog(
            transient_for=self.get_root(),
            heading=heading, body=body,
        )
        dialog.add_response("cancel",   "Cancel")
        dialog.add_response(action_id,  action_label)
        if destructive:
            dialog.set_response_appearance(action_id, Adw.ResponseAppearance.DESTRUCTIVE)
        dialog.connect("response", lambda d, r: on_confirm() if r == action_id else None)
        dialog.present()

    def _toast(self, message: str, error: bool = False):
        toast = Adw.Toast(title=message)
        toast.set_timeout(3)
        self._toast_overlay.add_toast(toast)
        if error:
            self._error_banner.set_title(message)
            self._error_banner.set_revealed(True)
            GLib.timeout_add_seconds(6, lambda: self._error_banner.set_revealed(False) or False)
        else:
            self._error_banner.set_revealed(False)
